function addBurst(x,y,color,n=8){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-100,100),vy:rand(-150,25),life:rand(.3,.7),max:.7,color,r:rand(2,5)})}
function drawParticles(dt){for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=220*dt;if(p.life<=0){particles.splice(i,1);continue}ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}
function spawn(){
  const lanePick=()=>Math.floor(rand(-1.45,1.45)+.5);
  const roll=Math.random();
  if(roll<.3){const l=lanePick();for(let j=0;j<4;j++)obstacles.push({type:'coin',l,d:spawnAt+j*4,phase:rand(0,6),hit:false})}
  else if(roll<.53){const safe=lanePick();for(let l=-1;l<=1;l++)if(l!==safe)obstacles.push({type:Math.random()<.5?'train':'crate',l,d:spawnAt,hit:false});for(let j=0;j<3;j++)obstacles.push({type:'coin',l:safe,d:spawnAt+j*4,phase:rand(0,6),hit:false})}
  else{const type=roll<.72?'crate':roll<.86?'beam':'train';obstacles.push({type,l:lanePick(),d:spawnAt,hit:false});if(Math.random()<.45){const l=lanePick();obstacles.push({type:'coin',l,d:spawnAt+7,phase:rand(0,6),hit:false})}}
  spawnAt+=rand(12,18)-Math.min(3,(speed-17)*.12);
}
function updateHud(){$('distance').textContent=String(Math.floor(score)).padStart(4,'0');$('coins').textContent=coins;$('best').textContent=String(best).padStart(4,'0');$('progress').style.width=`${(score%1000)/10}%`}
function showToast(text){$('toast').textContent=text;$('toast').classList.add('show');toastTimer=1.05}
function startGame(){
  mode='playing';score=0;coins=0;speed=17;spawnAt=15;obstacles=[];particles=[];lane=0;visualLane=0;jump=0;slide=0;shake=0;world=0;time=0;
  for(let i=0;i<6;i++)spawnAt+=rand(9,12);$('overlay').style.display='none';updateHud();last=performance.now();
}
function endGame(){mode='over';shake=.48;best=Math.max(best,Math.floor(score));localStorage.setItem('neon-run-best',best);updateHud();$('eyebrow').textContent='RUN COMPLETE';$('title').innerHTML='NICE<span>RUN</span>';$('message').textContent=`You covered ${Math.floor(score)} meters and collected ${coins} coins. The city is still calling.`;$('play').innerHTML='↻ &nbsp; RUN AGAIN';$('hint').textContent='TIP: JUMP OVER CRATES &nbsp;·&nbsp; SLIDE UNDER BARRIERS';$('overlay').style.display='grid'}
function doAction(action){
  if(mode!=='playing')return;
  if(action==='left')lane=clamp(lane-1,-1,1);if(action==='right')lane=clamp(lane+1,-1,1);
  if(action==='jump'&&jump<=0&&slide<=0)jump=.78;
  if(action==='slide'&&jump<=0)slide=.7;
}
function update(dt){time+=dt;if(mode==='playing'){
  const oldSpeed=speed;speed=Math.min(30,speed+dt*.19);world+=speed*dt;score+=speed*dt*.22;visualLane+=(lane-visualLane)*Math.min(1,dt*12);jump=Math.max(0,jump-dt);slide=Math.max(0,slide-dt);if(shake>0)shake=Math.max(0,shake-dt);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').classList.remove('show')}
  spawnAt-=speed*dt;if(spawnAt<0)spawn();
  for(let i=obstacles.length-1;i>=0;i--){const o=obstacles[i],before=o.d;o.d-=speed*dt;
    if(!o.hit&&o.type==='coin'&&before>8.5&&o.d<=8.5){if(Math.abs(o.l-visualLane)<.67){o.hit=true;coins++;const y=roadY(o.d),x=laneX(o.l,y);addBurst(x,y-30,'#ffd64a',9);showToast('+1 COIN')}}
    if(!o.hit&&o.type!=='coin'&&before>7.7&&o.d<=7.7){o.hit=true;if(Math.abs(o.l-lane)<.55){const safe=o.type==='crate'?jump>.25:o.type==='beam'?slide>.12:false;if(!safe){endGame();break}else{addBurst(laneX(o.l,roadY(o.d)),roadY(o.d)-25,'#58e5f1',7);showToast('CLEAN!')}}}
    if(o.d<-5||o.hit&&o.type==='coin'&&o.d<6)obstacles.splice(i,1)
  }
  if(Math.floor(score)!==Math.floor(score-speed*dt*.22))updateHud();
 }else if(mode==='over'&&shake>0){shake=Math.max(0,shake-dt)}
}

